import{_ as t,o,c as n,ag as r}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-22（地球科学 / 海岸带）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/earth-science/science-daily-2026-10-22-earth.md","filePath":"topics/earth-science/science-daily-2026-10-22-earth.md"}'),s={name:"topics/earth-science/science-daily-2026-10-22-earth.md"};function i(c,e,a,d,l,g){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="科学日报-·-2026-10-22-地球科学-海岸带" tabindex="-1">科学日报 · 2026-10-22（地球科学 / 海岸带） <a class="header-anchor" href="#科学日报-·-2026-10-22-地球科学-海岸带" aria-label="Permalink to &quot;科学日报 · 2026-10-22（地球科学 / 海岸带）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-22.md</code> — 第41期 ｜ 科学板块 落盘说明：文件名带 <code>-earth</code> 后缀以<strong>避免与其它主题同日同名文件互引产生伪边</strong>（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code> 及 10-21、10-22 晨报）。</p></blockquote><hr><h2 id="科学日报-2026-10-22-把整片盐沼搬进巨型造波机——极端风暴下盐沼护岸能力的真相" tabindex="-1">科学日报 2026-10-22：把整片盐沼搬进巨型造波机——极端风暴下盐沼护岸能力的真相 <a class="header-anchor" href="#科学日报-2026-10-22-把整片盐沼搬进巨型造波机——极端风暴下盐沼护岸能力的真相" aria-label="Permalink to &quot;科学日报 2026-10-22：把整片盐沼搬进巨型造波机——极端风暴下盐沼护岸能力的真相&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-22.md</code> ｜ DOI: 10.1038/s41586-026-11145-8</p></blockquote><ul><li>问题：盐沼靠<strong>抬高滩面 + 地上植被</strong>削减风浪，是重要的「基于自然的」海岸防护。但气候变化下这项服务能否持续，取决于<strong>极端风暴如何破坏滩面与植被</strong>——此前<strong>缺乏系统量化</strong>。</li><li>方法：<strong>把完整盐沼原状转移</strong>到世界最大的<strong>波浪水槽</strong>之一，逐级加大波高至 <strong>2 m 有效波高（significant wave height）</strong>。</li><li>结果（两套结构，命运相反）： <ul><li><strong>滩面基质</strong>：在累积波作用下<strong>侵蚀可忽略</strong>，保持稳定 → 「平台」比想象中抗打。</li><li><strong>植被</strong>：在持续波作用下<strong>被逐步破坏</strong>，植被相关的消浪能力随之下降 → 「软体」才是短板。</li><li><strong>量化</strong>：低能海岸（波高 ≤1 m）植被消浪 <strong>&gt;10%（最高约 50%）</strong>；高能海岸（波高 &gt;1 m）<strong>不超过 10%</strong>。</li><li>全球尺度评估支持这一「<strong>低能 / 高能</strong>」区分。</li></ul></li><li>结论：<strong>盐沼能扛住极端风暴的「结构」部分，但扛不住的是它的「功能」部分</strong>（植被被反复打断 → 消浪衰减）；且护岸收益高度依赖海岸本身的<strong>能量档位</strong>。</li><li>洞察（对本库 <code>earth-science</code>）：这是继 10-21（城市绿化降温<strong>回报递减</strong>）、10-20（冰崖不稳定性<strong>敏感依赖崖高之外</strong>的量）之后，<strong>同一元模式的第三个实例</strong>：<strong>「基于自然的解决方案」都自带一个随强度而变的收益曲线</strong>。附加的新结构是「<strong>损坏方式不对称</strong>」——<strong>承力结构（滩面）与功能部件（植被）的耐久性可以差一个量级</strong>，而人们往往只评估前者。这对本库 <code>wind-energy</code> 是个现成的类比：<strong>塔架/基础（承力）与叶片/控制（功能）的失效路径不同，可靠性评估不能只算承力件</strong>。</li></ul><hr><blockquote><p>📎 关联主题：<code>topics/earth-science/index.md</code> ｜ 第41期 科学板块</p></blockquote><p>关键词：盐沼、salt marsh、波浪水槽、wave flume、极端风暴、有效波高、significant wave height、消浪、wave attenuation、滩面侵蚀、植被破坏、低能海岸、高能海岸、基于自然的解决方案、收益随强度递减、损坏方式不对称、结构耐久性与功能耐久性</p><p>关联：<code>topics/earth-science/science-daily-2026-10-21-earth.md</code>（城市绿化降温回报递减 + 火星磁鞘喷流）、<code>topics/earth-science/science-daily-2026-10-20.md</code>（海洋冰崖不稳定性：单变量判断→多变量条件）、<code>topics/earth-science/2026-q3.md</code>、<code>topics/wind-energy/index.md</code></p>',10)])])}const m=t(s,[["render",i]]);export{p as __pageData,m as default};
